package com.hfr.packet.builder;
import java.util.*;import com.hfr.builder.*;import com.hfr.clowder.Clowder;import com.hfr.entity.EntityFactionBuilder;import com.hfr.schematic.*;import com.hfr.tileentity.machine.TileEntityMachineBuilder;import cpw.mods.fml.common.network.ByteBufUtils;import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;
public class BuilderDepotSnapshotPacket implements IMessage {public static BuilderDepotSnapshotPacket current;public int x,y,z;public String builder="",faction="",city="",state="IDLE",schematic="";public int progress,total,bx,by,bz;public boolean blocked;public final List<String> queue=new ArrayList<String>();public BuilderDepotSnapshotPacket(){}public static BuilderDepotSnapshotPacket create(TileEntityMachineBuilder d){BuilderDepotSnapshotPacket s=new BuilderDepotSnapshotPacket();s.x=d.xCoord;s.y=d.yCoord;s.z=d.zCoord;s.builder=d.getAssignedBuilderId()==null?"":d.getAssignedBuilderId().toString();Clowder c=d.getFactionId()==null?null:Clowder.getClowderFromUUID(d.getFactionId().toString());s.faction=c==null?"":c.name;s.city=d.getCityId();BuilderJobData data=BuilderJobData.get(d.getWorldObj());SchematicStoreData store=SchematicStoreData.get(d.getWorldObj());BuilderJob j=data==null?null:data.get(d.getActiveJobId());if(j!=null){s.state=j.state.name();Schematic sc=store==null?null:store.getSchematic(j.schematicId);s.schematic=sc==null?j.schematicId:sc.name;s.progress=j.blockIndex;s.total=sc==null?0:sc.size();s.bx=j.blockedX;s.by=j.blockedY;s.bz=j.blockedZ;s.blocked=j.state==BuilderState.INVALID_TERRITORY; }for(UUID id:d.getQueuedJobs()){BuilderJob q=data==null?null:data.get(id);if(q!=null){Schematic qs=store==null?null:store.getSchematic(q.schematicId);s.queue.add((qs==null?q.schematicId:qs.name)+" | "+q.state.name()+" | "+q.blockIndex+"/"+(qs==null?0:qs.size()));}}return s;}public void fromBytes(ByteBuf b){x=b.readInt();y=b.readInt();z=b.readInt();builder=str(b);faction=str(b);city=str(b);state=str(b);schematic=str(b);progress=b.readInt();total=b.readInt();blocked=b.readBoolean();bx=b.readInt();by=b.readInt();bz=b.readInt();int n=b.readUnsignedShort();for(int i=0;i<n;i++)queue.add(str(b));}public void toBytes(ByteBuf b){b.writeInt(x);b.writeInt(y);b.writeInt(z);put(b,builder);put(b,faction);put(b,city);put(b,state);put(b,schematic);b.writeInt(progress);b.writeInt(total);b.writeBoolean(blocked);b.writeInt(bx);b.writeInt(by);b.writeInt(bz);b.writeShort(queue.size());for(String q:queue)put(b,q);}private static String str(ByteBuf b){return ByteBufUtils.readUTF8String(b);}private static void put(ByteBuf b,String s){ByteBufUtils.writeUTF8String(b,s==null?"":s);}public static class Handler implements IMessageHandler<BuilderDepotSnapshotPacket,IMessage>{public IMessage onMessage(BuilderDepotSnapshotPacket m,MessageContext c){current=m;return null;}}}
